using System.IdentityModel.Tokens.Jwt;
using System.Security.Cryptography;
using System.Text.Json;
using LifeVerse.Api.Data;
using LifeVerse.Api.Modules.Worlds;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Assets;

public sealed record AssetPermissionRequest(Guid? UserId, Guid? GroupId, string PrincipalType, string Flags);
public sealed record InventoryFolderRequest(string Name, Guid? ParentId);
public sealed record InventoryItemUpdateRequest(string? DisplayName, Guid? FolderId, bool? IsFavorite = null);
public sealed record PlaceAssetRequest(Guid IslandId, float PositionX, float PositionY, float PositionZ, float RotationX, float RotationY, float RotationZ);
public sealed record EquipAssetRequest(string Slot);

public static class AssetEndpoints
{
    public static IEndpointRouteBuilder MapAssetEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var assets = endpoints.MapGroup("/api/v1/assets").WithTags("Assets").RequireAuthorization(); assets.MapPost("/upload", UploadAsync).DisableAntiforgery(); assets.MapGet("/{assetId:guid}/download", DownloadAsync); assets.MapPost("/{assetId:guid}/permissions", GrantPermissionAsync);
        var inventory = endpoints.MapGroup("/api/v1/inventory").WithTags("Inventory").RequireAuthorization(); inventory.MapGet("/items", ListAsync); inventory.MapGet("/folders", ListFoldersAsync); inventory.MapPost("/folders", CreateFolderAsync); inventory.MapPatch("/folders/{folderId:guid}", UpdateFolderAsync); inventory.MapDelete("/folders/{folderId:guid}", DeleteFolderAsync); inventory.MapPatch("/items/{itemId:guid}", UpdateItemAsync); inventory.MapPost("/items/{itemId:guid}/favorite", FavoriteAsync); inventory.MapDelete("/items/{itemId:guid}/favorite", UnfavoriteAsync); inventory.MapDelete("/items/{itemId:guid}", DeleteItemAsync); inventory.MapPost("/items/{itemId:guid}/restore", RestoreItemAsync); inventory.MapPost("/items/{itemId:guid}/copy", CopyItemAsync); inventory.MapPost("/items/{itemId:guid}/place", PlaceAsync); inventory.MapPost("/items/{itemId:guid}/equip", EquipAsync);
        return endpoints;
    }

    private static async Task<IResult> UploadAsync(HttpRequest request, HttpContext context, LifeVerseDbContext db, AssetStorageService storage, TimeProvider clock, CancellationToken ct)
    {
        if (!TryUser(context, out var owner)) return Results.Unauthorized(); var form = await request.ReadFormAsync(ct); var file = form.Files.GetFile("file"); var category = form["category"].ToString().Trim().ToLowerInvariant(); var allowedCategories = new[] { "objects", "textures", "sounds", "animations", "clothing", "accessories", "models" }; if (file is null || file.Length == 0 || !allowedCategories.Contains(category)) return Results.BadRequest(new { error = "A file and a valid category are required." });
        await using var input = file.OpenReadStream(); using var memory = new MemoryStream(); await input.CopyToAsync(memory, ct); var bytes = memory.ToArray(); var inspection = await AssetValidator.InspectAsync(file.FileName, file.ContentType, bytes, ct); if (!inspection.Valid) return Results.ValidationProblem(new Dictionary<string, string[]> { ["file"] = [inspection.Error!] }); var hash = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(); var duplicate = await db.AssetVersions.AsNoTracking().Include(x => x.Asset).SingleOrDefaultAsync(x => x.ContentHash == hash && x.Asset.DeletedAt == null, ct); if (duplicate is not null) { var nowDuplicate = clock.GetUtcNow(); db.InventoryItems.Add(new InventoryItem { Id = Guid.NewGuid(), OwnerUserId = owner, AssetId = duplicate.AssetId, DisplayName = duplicate.Asset.Name, CreatedAt = nowDuplicate, UpdatedAt = nowDuplicate }); await db.SaveChangesAsync(ct); return Results.Ok(new { assetId = duplicate.AssetId, reused = true, hash }); }
        var now = clock.GetUtcNow(); var name = Path.GetFileNameWithoutExtension(file.FileName); var asset = new Asset { Id = Guid.NewGuid(), OwnerUserId = owner, CreatorUserId = owner, Name = name[..Math.Min(name.Length, 160)], Category = category, Description = string.Empty, LicenseJson = "{\"source\":\"user-upload\"}", Status = "ready", CreatedAt = now, UpdatedAt = now }; var key = await storage.PutAsync(owner, hash, bytes, ct); var version = new AssetVersion { Id = Guid.NewGuid(), AssetId = asset.Id, Version = 1, ContentHash = hash, StorageKey = key, MimeType = inspection.MimeType, ByteSize = bytes.Length, Width = inspection.Width, Height = inspection.Height, DurationSeconds = inspection.DurationSeconds, ValidationJson = JsonSerializer.Serialize(new { inspected = true, geometryLimit = 100000 }), CreatedAt = now }; db.Assets.Add(asset); db.AssetVersions.Add(version); db.InventoryItems.Add(new InventoryItem { Id = Guid.NewGuid(), OwnerUserId = owner, AssetId = asset.Id, DisplayName = asset.Name, CreatedAt = now, UpdatedAt = now }); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/assets/{asset.Id}", new { assetId = asset.Id, version = 1, hash, category, mimeType = inspection.MimeType, width = inspection.Width, height = inspection.Height });
    }

    private static async Task<IResult> ListAsync(HttpContext context, string? search, string? category, Guid? folderId, bool includeDeleted, bool favoritesOnly, int page, int pageSize, LifeVerseDbContext db, CancellationToken ct)
    {
        if (!TryUser(context, out var owner)) return Results.Unauthorized(); page = Math.Max(1, page); pageSize = Math.Clamp(pageSize, 1, 100); var query = db.InventoryItems.AsNoTracking().Where(x => x.OwnerUserId == owner && (includeDeleted || x.DeletedAt == null)).Join(db.Assets, item => item.AssetId, asset => asset.Id, (item, asset) => new { item, asset }).Where(x => includeDeleted || x.asset.DeletedAt == null); if (folderId is not null) query = query.Where(x => x.item.FolderId == folderId); if (favoritesOnly) query = query.Where(x => x.item.IsFavorite); if (!string.IsNullOrWhiteSpace(search)) query = query.Where(x => x.item.DisplayName.Contains(search) || x.asset.Name.Contains(search)); if (!string.IsNullOrWhiteSpace(category)) query = query.Where(x => x.asset.Category == category.ToLower()); var total = await query.CountAsync(ct); var items = await query.OrderByDescending(x => x.item.IsFavorite).ThenByDescending(x => x.item.CreatedAt).Skip((page - 1) * pageSize).Take(pageSize).Select(x => new { itemId = x.item.Id, assetId = x.asset.Id, name = x.item.DisplayName, category = x.asset.Category, version = x.asset.CurrentVersion, size = db.AssetVersions.Where(v => v.AssetId == x.asset.Id && v.Version == x.asset.CurrentVersion).Select(v => v.ByteSize).FirstOrDefault(), creatorUserId = x.asset.CreatorUserId, ownerUserId = x.item.OwnerUserId, favorite = x.item.IsFavorite, deleted = x.item.DeletedAt != null, createdAt = x.item.CreatedAt, updatedAt = x.item.UpdatedAt }).ToListAsync(ct); return Results.Ok(new { page, pageSize, total, items });
    }

    private static async Task<IResult> ListFoldersAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); return Results.Ok(await db.InventoryFolders.AsNoTracking().Where(x => x.OwnerUserId == owner && x.DeletedAt == null).OrderBy(x => x.Name).ToListAsync(ct)); }

    private static async Task<IResult> CreateFolderAsync(InventoryFolderRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var name = request.Name.Trim(); if (name.Length is < 1 or > 120) return Results.ValidationProblem(new Dictionary<string, string[]> { ["name"] = ["Folder name is invalid."] }); var now = clock.GetUtcNow(); var folder = new InventoryFolder { Id = Guid.NewGuid(), OwnerUserId = owner, ParentId = request.ParentId, Name = name, CreatedAt = now, UpdatedAt = now }; db.InventoryFolders.Add(folder); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/inventory/folders/{folder.Id}", folder); }
    private static async Task<IResult> UpdateItemAsync(Guid itemId, InventoryItemUpdateRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); if (request.DisplayName is not null) item.DisplayName = request.DisplayName.Trim()[..Math.Min(request.DisplayName.Trim().Length, 160)]; item.FolderId = request.FolderId; if (request.IsFavorite is not null) item.IsFavorite = request.IsFavorite.Value; item.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(item); }
    private static async Task<IResult> FavoriteAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => await SetFavoriteAsync(itemId, true, context, db, clock, ct);
    private static async Task<IResult> UnfavoriteAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => await SetFavoriteAsync(itemId, false, context, db, clock, ct);
    private static async Task<IResult> SetFavoriteAsync(Guid itemId, bool value, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); item.IsFavorite = value; item.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(new { itemId, favorite = value }); }
    private static async Task<IResult> UpdateFolderAsync(Guid folderId, InventoryFolderRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var folder = await db.InventoryFolders.SingleOrDefaultAsync(x => x.Id == folderId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (folder is null) return Results.NotFound(); var name = request.Name.Trim(); if (name.Length is < 1 or > 120) return Results.BadRequest(); folder.Name = name; folder.ParentId = request.ParentId; folder.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(folder); }
    private static async Task<IResult> DeleteFolderAsync(Guid folderId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var folder = await db.InventoryFolders.SingleOrDefaultAsync(x => x.Id == folderId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (folder is null) return Results.NotFound(); folder.DeletedAt = clock.GetUtcNow(); await db.InventoryItems.Where(x => x.OwnerUserId == owner && x.FolderId == folderId && x.DeletedAt == null).ExecuteUpdateAsync(x => x.SetProperty(i => i.FolderId, (Guid?)null), ct); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> DeleteItemAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); item.DeletedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> RestoreItemAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner, ct); if (item is null) return Results.NotFound(); item.DeletedAt = null; await db.SaveChangesAsync(ct); return Results.Ok(item); }
    private static async Task<IResult> CopyItemAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var source = await db.InventoryItems.AsNoTracking().SingleOrDefaultAsync(x => x.Id == itemId && x.DeletedAt == null, ct); if (source is null) return Results.NotFound(); var asset = await db.Assets.AsNoTracking().SingleAsync(x => x.Id == source.AssetId, ct); if (asset.OwnerUserId != owner && !await db.AssetPermissions.AnyAsync(x => x.AssetId == asset.Id && x.UserId == owner && x.RevokedAt == null && x.Flags.Contains("copy"), ct)) return Results.Forbid(); var now = clock.GetUtcNow(); var copy = new InventoryItem { Id = Guid.NewGuid(), OwnerUserId = owner, AssetId = asset.Id, DisplayName = source.DisplayName + " Copy", CreatedAt = now, UpdatedAt = now }; db.InventoryItems.Add(copy); await db.SaveChangesAsync(ct); return Results.Ok(copy); }
    private static async Task<IResult> GrantPermissionAsync(Guid assetId, AssetPermissionRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var asset = await db.Assets.SingleOrDefaultAsync(x => x.Id == assetId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (asset is null) return Results.NotFound(); if (request.PrincipalType is not ("user" or "group") || request.Flags.Length > 256) return Results.BadRequest(); var permission = new AssetPermission { Id = Guid.NewGuid(), AssetId = assetId, UserId = request.UserId, GroupId = request.GroupId, PrincipalType = request.PrincipalType, Flags = request.Flags.ToLowerInvariant(), CreatedAt = clock.GetUtcNow() }; db.AssetPermissions.Add(permission); await db.SaveChangesAsync(ct); return Results.Ok(permission); }
    private static async Task<IResult> DownloadAsync(Guid assetId, HttpContext context, LifeVerseDbContext db, AssetStorageService storage, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var asset = await db.Assets.AsNoTracking().SingleOrDefaultAsync(x => x.Id == assetId && x.DeletedAt == null, ct); if (asset is null) return Results.NotFound(); if (asset.OwnerUserId != owner && !await db.AssetPermissions.AnyAsync(x => x.AssetId == assetId && x.UserId == owner && x.RevokedAt == null && (x.Flags.Contains("use") || x.Flags.Contains("copy")), ct)) return Results.Forbid(); var version = await db.AssetVersions.AsNoTracking().SingleAsync(x => x.AssetId == assetId && x.Version == asset.CurrentVersion, ct); var stream = await storage.OpenReadAsync(version.StorageKey, ct); return stream is null ? Results.NotFound() : Results.File(stream, version.MimeType, asset.Name + Path.GetExtension(version.StorageKey)); }
    private static async Task<IResult> EquipAsync(Guid itemId, EquipAssetRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.AsNoTracking().SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); var avatar = await db.Avatars.Include(x => x.EquippedItems).SingleOrDefaultAsync(x => x.UserId == owner, ct); if (avatar is null) return Results.NotFound(); var slot = request.Slot.Trim().ToLowerInvariant(); var existing = avatar.EquippedItems.SingleOrDefault(x => x.Slot == slot); if (existing is null) db.EquippedItems.Add(new EquippedItem { Id = Guid.NewGuid(), AvatarId = avatar.Id, Slot = slot, ItemKey = $"asset:{item.AssetId}", TintColor = "#FFFFFF", EquippedAt = clock.GetUtcNow() }); else { existing.ItemKey = $"asset:{item.AssetId}"; existing.EquippedAt = clock.GetUtcNow(); } await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> PlaceAsync(Guid itemId, PlaceAssetRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.AsNoTracking().SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == request.IslandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (island.OwnerUserId != owner && !await db.IslandPermissions.AnyAsync(x => x.IslandId == island.Id && x.UserId == owner && x.RevokedAt == null && (x.Permission == "build" || x.Permission == "admin"), ct)) return Results.Forbid(); var now = clock.GetUtcNow(); var placed = new WorldAssetInstance { Id = Guid.NewGuid(), IslandId = island.Id, AssetId = item.AssetId, OwnerUserId = owner, PositionX = request.PositionX, PositionY = request.PositionY, PositionZ = request.PositionZ, RotationX = request.RotationX, RotationY = request.RotationY, RotationZ = request.RotationZ, CreatedAt = now, UpdatedAt = now }; db.WorldAssetInstances.Add(placed); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/worlds/islands/{island.Id}/assets/{placed.Id}", placed); }
    private static bool TryUser(HttpContext context, out Guid id) => Guid.TryParse(context.User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value, out id);
}
